const {test}=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path'),vm=require('node:vm'),{execFileSync}=require('node:child_process'),{parse,walk}=require('../audits/audit-i18n-global.cjs');
const root=path.resolve(__dirname,'../..'),read=f=>fs.readFileSync(path.join(root,f),'utf8'),manifest=JSON.parse(read('outils/audits/I18N-ONGLET-ORGANISATIONS-871-sources.json')),base=manifest.baseCommit,proofPath=path.join(root,'outils/audits/I18N-ONGLET-ORGANISATIONS-871-preuve.json'),proof=fs.existsSync(proofPath)?JSON.parse(fs.readFileSync(proofPath)):null,at=(sha,f)=>execFileSync('git',['show',sha+':'+f],{cwd:root,encoding:'utf8',maxBuffer:4e6}),code=f=>proof?at(proof.codeCommit,f):read(f),strip=n=>!n||typeof n!=='object'?n:Array.isArray(n)?n.map(strip):Object.fromEntries(Object.entries(n).filter(([k])=>!['start','end','loc','raw'].includes(k)).map(([k,v])=>[k,strip(v)]));
const catalogs=['i18n/resources.js','i18n/plateau-resources.js','i18n/orders-resources.js','i18n/order-variants-resources.js','i18n/sovarka-partis-resources.js','i18n/organization-directory-resources.js','i18n/organization-creation-resources.js','i18n/organization-admissions-resources.js','i18n/organization-settings-resources.js','i18n/organization-panel-resources.js'];
